  // alle ~8-12px. Innen bleibt das dunkle Tiefen-Band (n) der Bestands-Zeilen.
  // GP6 §6.4b — UFER-ENTREGELUNG. Die vier geraden Ufer-Tiles trugen je DREI
  // durchgehende 16px-Wasserlinien uebereinander ("Becken-Raster"). Jetzt
  // bleibt genau EINE Linie stehen (shore_n Zeile 1, shore_s Zeile 14,
