  // §3.7 Boss-Boden-Decals — GFX4-R2 (Jury K4/K5, "groesster Einzelfehler": die
  // R1-Grids hatten eigenen dunklen Grund und lasen als Fehltile/Loch). NEUAUFBAU
  // auf einer KOPIE des stone_floor-Grids (Basis byte-nah am Boden-Ton, keine
