  // GP5-R2 BOSS-KRATZER (Jury ART-5): die Kratzer lagen im kalten Blaugrau
  // 'L'/'D' (#687180 = (104,113,128)) und lasen als Lichtreflex statt als
  // Schramme. Umgefaerbt auf 'O' (#6e6655 = (110,102,85)) — der Bestandston,
  // der dem Jury-Ziel (108,104,96) am naechsten liegt — und die begleitende
  // Linie auf 'k' gezogen: jeder Kratzer hat jetzt 1px SCHATTEN rechts/unter
  // sich und liest als Vertiefung. Nur die Kratzer-Pixel sind angefasst, der
  // geerbte stone_floor-Untergrund ist Pixel fuer Pixel unveraendert.
  // GP5-R3 (Jury R2, ART-Auftrag 4): die R2-Umfaerbung kam WARM/KHAKI an — 'O'
  // (#6e6655) gehoert zur KNOCHEN-Rampe, nicht zur Steinrampe, und stach als
  // gelblicher Fremdkoerper aus dem kalten Boden. Der Auftrag lautet "kalte
  // L/D-Rampe, 2 Stufen dunkler": die 12 Kratzerpixel stehen jetzt auf 'T'
  // (#4a4a45, Luminanz 73,4) — zwei Stufen unter dem R1-Ton 'D' (156,8) bzw.
  // eine unter 'L' (112,0), und damit nur noch 28 statt 66 Luminanzstufen ueber
  // dem Bodenton 't' (45,7): eine Schramme, kein Lichtreflex. Die begleitende
  // 1px-Unterkante bleibt der kalte Tiefstton 'k' (18,3).
  // GP6 §6.2 — KRATZER KALT. 'T' (#4a4a45, R-B = +5) und 'm' (#5f7250 nach
  // dem Offset, R-B = +15) sind die einzigen WARMEN Toene auf dem kalten
  // Boss-Boden ('t', R-B = -12); gegen ihn gemessen liegen sie +17 bzw. +27 —
  // die Auflage ist <= +8. Beide Toene sind deshalb aus dem GESAMTEN Grid
  // entfernt (nicht nur aus der Kratzerlinie, sonst bliebe der Waechter rot).
  // Ersatz: L+k-DITHER nach Paritaet (x+y) — L (R-B = -24) und k (R-B = -6)
  // mitteln auf -15, also 3 Stufen KUEHLER als der Boden. Der 1px-'m'-Moos-
  // tupfer, den das Grid vom stone_floor geerbt hatte, wird 'n'.
