  // §3.7 Wiesenlicht-Makro (NEU): nahtlose hellere/dunklere Gras-Basis aus der
  // Bestands-Gras-Rampe (e<E<a<m<K). Vollflaechig opak. Gen: .tmp/gen_gfx4_art.mjs.
  //
  // ===== GP5 RUNDE 2 — ART-GATE-FIX 4 (Wiesenlicht liest als 16px-Quadrate) =====
  // Beobachtung: die hellen H-/L-Kacheln zeigen ihre Kachelform, weil ihr Rand
  // bis an die Kachelkante voll deckt. Beide Grids bekommen jetzt einen
  // ERODIERTEN Rand aus 'e'/'E' (Gen/Messung: .tmp/gen_grass_gp5r2fix.mjs).
  // WICHTIG — warum BISSE und kein umlaufendes Band: ein gleichmaessig dichter
  // 1-2px-Saum wuerde zwischen zwei benachbarten H-Kacheln eine durchgehende
  // 2px-Linie alle 16px erzeugen — also genau das Raster, das er brechen soll.
  // Der Saum besteht deshalb aus unregelmaessigen Segmenten von 2-5px mit
  // Luecken >= 3px, Tiefe 1px (jeder zweite Biss 2px), je Kante ein eigenes
  // Profil aus einem dekorrelierten Ganzzahl-Mischer (hash-frei im Sinne von
  // §0.4: der Mischer laeuft im Generator, hier stehen nur feste Pixel).
  // NACHGEMESSEN: laengster ununterbrochener Saum-Lauf 5px, kleinste Luecke
  // 4px; erodiert sind lumahi 39 px (15,2 %), lumalo 16 px (6,3 % — dort war
  // ein Teil des Randes schon 'e'). Keine Kachelkontur, gebrochene Silhouette.
  // ===== GRAFIKPASS 6 §3.1 — WIESENLICHT NEU GESTUFT =====================
  // Der Paletten-Offset hebt die ganze Gras-Rampe um 15 L; das Pool-Mittel des
  // 47er-Gras-Pools liegt damit bei 49,9 L. Die sechs Wiesenlicht-Klassen
  // standen vorher 5 bis 30 L ueber dem Pool ("16px-Quadrate") — Spec §3.1
  // verlangt jetzt ein Kachelmittel von +-2..4 L um das Pool-Mittel. Umgesetzt
  // als reiner TON-AUSTAUSCH: die GP5-Stempelgeometrie (Klumpen, erodierter
  // Rand, kleinste Periode 16 in beiden Achsen) ist unveraendert uebernommen,
  // nur die Ton-BELEGUNG je Texel ist neu. Reihenfolge nach Original-Helligkeit
  // plus Klumpenmass -> die hellsten Bestandstexel bleiben die hellsten.
  // Rampe: '+' (35,5) < e (46,9) < E (61,1) < a (82,7). '+' ist der einzige
  // dunkelgruene Ton UNTER dem neuen 'e' (§3.1 laesst k/n/0/*/+ bewusst unten)
  // und traegt die Schattenpockets der lo-Klassen — ohne ihn waeren die
  // dunklen Kacheln nach dem Offset flaches, texturloses 'e'.
  // NACHZUG NOETIG (Phase 3, check_gfx6_art): der portierte mix75-Dichte-
  // waechter zaehlt heute den Patch-Ton 'a' bzw. 'E' und fordert 160..224.
  // Das ist mit dem +-2..4-L-Band arithmetisch unvereinbar (194 Texel eines
  // Tons ueber 'e' ergeben mindestens 57,6 L = Pool +7,7). Neue Sollwerte
  // stehen im Uebergabetext.
