  // Tiefton: genau EINE Glyphe je belegter Spalte, senkrechte Laeufe 4-7 px,
  // Phasen aus einem linearen Hash-Schritt, Nachbarspalten mindestens 3 Zeilen
  // versetzt (auch ueber die Naht 15<->0), MAX EIN 1px-Seitenversatz je Glyphe
  // und der faellt deterministisch weg, sobald er einen waagerechten Lauf > 2
  // erzeugen wuerde. Zusaetzlich ist NIE eine dritte Nachbarspalte belegt —
  // damit ist der waagerechte Lauf <= 2 strukturell garantiert (Haken- und
  // T-Formen = die GP5-R2-"Leiterbahnen" koennen gar nicht entstehen).
