  // ===== GRAFIKPASS 6 §5.1/§5.2/§5.3 — XL-KRONEN =========================
  // Drei neue Kronen-Klassen ueber MEHRERE Kacheln: xl_a 48x32 (span 3x2),
  // xl_b 64x48 (span 4x3, traegt die M4-Beweiszelle), xl_c 48x32 (span 3x2),
  // je zusaetzlich gespiegelt (_m) und je mit FUENF gebackenen Scher-Posen
  // (Basis, _r1, _r2, _l1, _l2). Die Legende faehrt daraus den 8er-Zyklus
  // [0,+1,+2,+1,0,-1,-2,-1]; poses[0] IST der Basis-Key und die UNTERKANTE
  // jeder Pose ist byte-identisch zur Basis (der Stammanschluss darf nicht
  // wackeln). Toene ausschliesslich Bestand: 0 < E < a < m < K < A plus
  // 'n'-Naehte zwischen den Blattballen (NICHT 'k' — L<16-Budget §5.1).
  // Die Aufhellung kommt aus dem Paletten-Offset, nicht aus mehr hellen Texeln:
  // das Kachelmittel liegt bei 79 L und damit auf dem Wert der Bestandskronen.
  // KUENSTLERISCHE NACHARBEIT gegenueber dem P0b-Entwurf (dessen drei
  // dokumentierte Schwaechen):
  //  1. SILHOUETTE FEST statt verrauscht — die Lappen-Radien werden nicht mehr
  //     je Pixel aus weissem Rauschen moduliert, sondern ueber eine
  //     WINKELFUNKTION (zwei Sinus-Terme mit deterministischen Phasen); danach
  //     zwei Runden Morphologie (Sporen weg, Kerben zu). Gemessen: 0 Texel mit
  //     nur einem gefuellten 4er-Nachbarn.
  //  2. SPITZLICHT OBEN LINKS STAERKER — es laeuft jetzt an allen nach oben
  //     ODER links offenen Kanten, ist zwei Texel tief (A ueber K) und faellt
  //     mit dem Abstand zur oberen linken Ecke ab (solide Kappe, dann 1/7,
  //     dann 3/7 Luecken, ab s = 1,05 nichts). Damit liest die LICHTRICHTUNG,
  //     nicht eine umlaufende Aussenlinie. Laengste zusammenhaengende
  //     A-Kappe 7-12 px.
  //  3. '0'-KONTURENSAUM wie bei den Bestandskronen — jeder Randtexel mit
  //     freiem Nachbarn RECHTS oder UNTEN wird '0', an der Unterkante zwei
  //     Texel tief. Oben/links bleibt der Saum frei (dort sitzt das Spitzlicht).
